// HasCampaign applies the HasEdge predicate on the "campaign" edge.
func HasCampaign() predicate.NotificationCampaignConfirmation {
	return predicate.NotificationCampaignConfirmation(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CampaignTable, CampaignColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCampaignWith applies the HasEdge predicate on the "campaign" edge with a given conditions (other predicates).
func HasCampaignWith(preds ...predicate.NotificationCampaign) predicate.NotificationCampaignConfirmation {
	return predicate.NotificationCampaignConfirmation(func(s *sql.Selector) {
		step := newCampaignStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.NotificationCampaignConfirmation) predicate.NotificationCampaignConfirmation {
	return predicate.NotificationCampaignConfirmation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.NotificationCampaignConfirmation) predicate.NotificationCampaignConfirmation {
	return predicate.NotificationCampaignConfirmation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.NotificationCampaignConfirmation) predicate.NotificationCampaignConfirmation {
	return predicate.NotificationCampaignConfirmation(sql.NotPredicates(p))
}
